UPDATE integrated_user
SET nickname = #{nickname}, email = #{email}, age = #{age}
WHERE user_id = #{userId}

UPDATE integrated_user
SET is_suspended = TRUE, suspended_reason = #{reason}, suspended_at = NOW()
WHERE user_id = #{userId}

UPDATE integrated_user
SET is_suspended = FALSE, suspended_reason = NULL, suspended_at = NULL
WHERE user_id = #{userId}

UPDATE integrated_user
SET is_author = TRUE, pen_name = #{penName}
WHERE user_id = #{userId}
